package com.newapp.fieldreport
import java.io.File
import java.io.FileOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream
object XlsxWriter{
 private const val H="<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>"
 fun write(file:File,p:List<Project>,i:List<Item>,e:List<Entry>){val sheets=listOf("Projects" to (listOf("Project_ID","Project_Name","Project_Name_AR") to p.map{listOf<Any>(it.code,it.name,it.nameAr)}),"Items" to (listOf("Item_ID","Item_Name","Item_Name_AR","Unit","Category") to i.map{listOf<Any>(it.code,it.name,it.nameAr,it.unit,it.category)}),"Entries" to (listOf("Record_ID","Role","Record_Type","Project_ID","Item_ID","Item_Name","Unit","Quantity","Hours","Status","Priority","Person_Code","Person_Name","Recorded_At","Notes") to e.map{listOf<Any>(it.id,it.role,it.recordType,it.projectCode,it.itemCode,it.itemName,it.unit,it.quantity?:"",it.hours?:"",it.status,it.priority,it.personCode,it.personName,it.eventAt,it.notes)}));ZipOutputStream(FileOutputStream(file)).use{z->add(z,"[Content_Types].xml",types(sheets.size));add(z,"_rels/.rels",root());add(z,"xl/workbook.xml",book(sheets));add(z,"xl/_rels/workbook.xml.rels",bookRel(sheets.size));sheets.forEachIndexed{n,sh->add(z,"xl/worksheets/sheet${n+1}.xml",sheet(sh.second.first,sh.second.second))}}}
 private fun add(z:ZipOutputStream,n:String,s:String){z.putNextEntry(ZipEntry(n));z.write(s.toByteArray());z.closeEntry()}
 private fun types(n:Int)=H+"<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>"+(1..n).joinToString(""){ "<Override PartName=\"/xl/worksheets/sheet$it.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>"}+"</Types>"
 private fun root()=H+"<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>"
 private fun book(s:List<Pair<String,Pair<List<String>,List<List<Any>>>>>)=H+"<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>"+s.mapIndexed{n,x->"<sheet name=\"${x.first}\" sheetId=\"${n+1}\" r:id=\"rId${n+1}\"/>"}.joinToString("")+"</sheets></workbook>"
 private fun bookRel(n:Int)=H+"<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"+(1..n).joinToString(""){ "<Relationship Id=\"rId$it\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet$it.xml\"/>"}+"</Relationships>"
 private fun sheet(h:List<String>,rows:List<List<Any>>):String{val s=StringBuilder(H+"<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView rightToLeft=\"1\" workbookViewId=\"0\"/></sheetViews><sheetData>");row(s,1,h);rows.forEachIndexed{x,r->row(s,x+2,r)};return s.append("</sheetData></worksheet>").toString()}
 private fun row(s:StringBuilder,n:Int,v:List<Any>){s.append("<row r=\"$n\">");v.forEachIndexed{x,a->val ref="${('A'.code+x).toChar()}$n";if(a is Number)s.append("<c r=\"$ref\"><v>$a</v></c>")else s.append("<c r=\"$ref\" t=\"inlineStr\"><is><t xml:space=\"preserve\">${esc(a.toString())}</t></is></c>")};s.append("</row>")}
 private fun esc(x:String)=x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;")
}
